/**
 * @summary Claim a CAD job from a trusted Fusion worker
 */
export const ClaimFusionJobParams = zod.object({
  "job_id": zod.coerce.string()
})

export const ClaimFusionJobHeader = zod.object({
  "X-Trinity-Worker-Secret": zod.string()
})

export const claimFusionJobBodyExpiresInSecondsDefault = 300;

export const ClaimFusionJobBody = zod.object({
  "worker_id": zod.string(),
  "expires_in_seconds": zod.number().default(claimFusionJobBodyExpiresInSecondsDefault)
})

export const ClaimFusionJobResponse = zod.unknown()


/**
 * @summary Upload a Fusion export artifact
 */
export const UploadFusionArtifactParams = zod.object({
  "job_id": zod.coerce.string()
})

export const UploadFusionArtifactHeader = zod.object({
  "X-Trinity-Worker-Secret": zod.string()
})

export const UploadFusionArtifactBody = zod.object({
  "file": zod.custom<File>((value) => typeof File !== 'undefined' && value instanceof File),
  "token": zod.string(),
  "kind": zod.string().optional()
})

export const UploadFusionArtifactResponse = zod.unknown()


/**
 * @summary Complete a Fusion job with validation and artifact IDs
 */
export const CompleteFusionJobParams = zod.object({
  "job_id": zod.coerce.string()
})

export const CompleteFusionJobHeader = zod.object({
  "X-Trinity-Worker-Secret": zod.string()
})

export const CompleteFusionJobBody = zod.object({
  "token": zod.string(),
  "status": zod.string(),
  "artifact_ids": zod.array(zod.string()).optional(),
  "validation_status": zod.string().optional(),
  "checks": zod.array(zod.object({

})).optional(),
  "fusion_version": zod.string().nullish(),
  "addin_version": zod.string().nullish(),
  "error": zod.string().nullish()
})

export const CompleteFusionJobResponse = zod.unknown()
